namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace RecipeShare.Models;

using System.ComponentModel.DataAnnotations;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Recipe title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please add a short description.")]
    [StringLength(500, MinimumLength = 10, ErrorMessage = "Description must be between 10 and 500 characters.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please list the ingredients.")]
    [MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please describe the steps.")]
    [MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals to keep you energized" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats to satisfy your cravings" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
        new() { Name = "Drinks", Icon = "🥤", Description = "Refreshing beverages and smoothies" },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for weekend mornings.",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
            Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just blended.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown."],
            TotalRatings = 12, RatingSum = 52,
        },
        new()
        {
            Id = 2, Title = "Caesar Salad", Category = "Lunch",
            Description = "Crisp romaine with homemade Caesar dressing and crunchy croutons.",
            Ingredients = ["1 head romaine lettuce", "½ cup parmesan cheese", "1 cup croutons", "2 cloves garlic", "2 anchovy fillets", "1 egg yolk", "1 tbsp Dijon mustard", "¼ cup olive oil", "Juice of 1 lemon"],
            Steps = ["Wash and chop the romaine lettuce.", "Mince garlic and anchovy fillets into a paste.", "Whisk egg yolk, mustard, garlic-anchovy paste, and lemon juice.", "Slowly drizzle in olive oil while whisking to emulsify.", "Toss lettuce with dressing, parmesan, and croutons.", "Serve immediately."],
            TotalRatings = 8, RatingSum = 35,
        },
        new()
        {
            Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich and hearty Italian meat sauce over al dente pasta.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g canned tomatoes", "2 tbsp tomato paste", "1 tsp oregano", "Salt and pepper to taste", "Parmesan for serving"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, drain excess fat.", "Sauté onion and garlic until softened.", "Add canned tomatoes, tomato paste, and oregano.", "Simmer sauce for 20 minutes, stirring occasionally.", "Season with salt and pepper, serve over spaghetti with parmesan."],
            TotalRatings = 15, RatingSum = 68,
        },
        new()
        {
            Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Warm chocolate cake with a gooey molten center.",
            Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "3 egg yolks", "¼ cup sugar", "2 tbsp flour"],
            Steps = ["Preheat oven to 220°C (425°F).", "Melt chocolate and butter together in a double boiler.", "Whisk eggs, egg yolks, and sugar until thick.", "Fold chocolate mixture into the eggs, then fold in flour.", "Grease ramekins and dust with cocoa powder.", "Pour batter into ramekins and bake for 12–14 minutes.", "Invert onto plates and serve immediately."],
            TotalRatings = 20, RatingSum = 95,
        },
        new()
        {
            Id = 5, Title = "Guacamole", Category = "Snacks",
            Description = "Fresh and zesty avocado dip with a kick of lime.",
            Ingredients = ["3 ripe avocados", "1 lime, juiced", "½ tsp salt", "½ cup diced onion", "1 jalapeño, minced", "2 tbsp cilantro", "1 diced tomato"],
            Steps = ["Halve avocados, remove pit, and scoop into a bowl.", "Mash avocado with a fork to desired consistency.", "Stir in lime juice and salt.", "Mix in onion, jalapeño, cilantro, and tomato.", "Serve immediately with tortilla chips."],
            TotalRatings = 10, RatingSum = 44,
        },
        new()
        {
            Id = 6, Title = "Mango Smoothie", Category = "Drinks",
            Description = "A tropical, creamy smoothie bursting with mango flavor.",
            Ingredients = ["2 ripe mangoes, peeled and diced", "1 cup yogurt", "½ cup milk", "2 tbsp honey", "1 cup ice cubes"],
            Steps = ["Combine mango, yogurt, milk, and honey in a blender.", "Add ice cubes.", "Blend until smooth and creamy.", "Pour into glasses and serve immediately."],
            TotalRatings = 6, RatingSum = 27,
        },
    ];

    private int _nextId = 7;

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };
        _recipes.Add(recipe);
    }
}

