+@using RecipeShare.Services
+
+@inject RecipeService RecipeService
+
+<div class="my-3">
+    <span class="me-2 fw-semibold">Rate this recipe:</span>
+    @for (int i = 1; i <= 5; i++)
+    {
+        var star = i;
+        <span
+            @onclick="() => SubmitRating(star)"
+            @onmouseover="() => hoverStar = star"
+            @onmouseout="() => hoverStar = 0"
+            style="cursor: pointer; font-size: 1.5rem; color: @(GetStarColor(star));"
+            role="button"
+            aria-label="Rate @star stars">★</span>
+    }
+    @if (rated)
+    {
+        <span class="ms-2 text-success">✓ Thanks for rating!</span>
+    }
+    <div class="text-muted small mt-1">
+        Average: @currentAverage.ToString("0.0") / 5 (@totalRatings ratings)
+    </div>
+</div>
+
+@code {
+    [Parameter] public int RecipeId { get; set; }
+    [Parameter] public double CurrentAverage { get; set; }
+    [Parameter] public int TotalRatings { get; set; }
+
+    private int hoverStar;
+    private int selectedStar;
+    private bool rated;
+    private double currentAverage;
+    private int totalRatings;
+
+    protected override void OnParametersSet()
+    {
+        currentAverage = CurrentAverage;
+        totalRatings = TotalRatings;
+    }
+
+    private string GetStarColor(int star)
+    {
+        if (hoverStar > 0)
+            return star <= hoverStar ? "gold" : "#ccc";
+        if (selectedStar > 0)
+            return star <= selectedStar ? "gold" : "#ccc";
+        return star <= Math.Round(currentAverage) ? "gold" : "#ccc";
+    }
+
+    private void SubmitRating(int stars)
+    {
+        if (rated) return;
+
+        RecipeService.AddRating(RecipeId, stars);
+        selectedStar = stars;
+        rated = true;
+
+        var recipe = RecipeService.GetRecipeById(RecipeId);
+        if (recipe is not null)
+        {
+            currentAverage = recipe.AverageRating;
